// HasObservations applies the HasEdge predicate on the "observations" edge.
func HasObservations() predicate.SourceRun {
	return predicate.SourceRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ObservationsTable, ObservationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasObservationsWith applies the HasEdge predicate on the "observations" edge with a given conditions (other predicates).
func HasObservationsWith(preds ...predicate.SourceObservation) predicate.SourceRun {
	return predicate.SourceRun(func(s *sql.Selector) {
		step := newObservationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SourceRun) predicate.SourceRun {
	return predicate.SourceRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SourceRun) predicate.SourceRun {
	return predicate.SourceRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SourceRun) predicate.SourceRun {
	return predicate.SourceRun(sql.NotPredicates(p))
}
